require 'includes/auth_helpers.php'; require 'includes/db.php'; require_once 'includes/psgc_helpers.php';
$errors=[]; $saved=false;
$positions=['Service Crew','Kitchen Crew','Cashier','Shift Leader','Branch Supervisor','Assistant Branch Manager','Branch Manager','Area Manager','Operations Manager','Human Resources Manager','Marketing Manager','Finance and Accounting Manager','Supply Chain Manager','Training Manager','Other'];
if ($_SERVER['REQUEST_METHOD']==='POST') {
  if (!csrf_check($_POST['csrf']??null)) $errors[]='Your session expired. Please try again.';
  $d=[]; foreach (['purpose','first_name','middle_name','last_name','position_applied','phone','street_address','region_code','municipality_code','barangay_code','zip_code','email'] as $k) $d[$k]=trim((string)($_POST[$k]??''));
  if (!in_array($d['purpose'],['Employment','Internship','Part-time'],true) || !in_array($d['position_applied'],$positions,true) || !preg_match(NAME_RE,$d['first_name']) || !preg_match(NAME_RE,$d['last_name']) || ($d['middle_name']!==''&&!preg_match(NAME_RE,$d['middle_name'])) || !$d['street_address'] || mb_strlen($d['street_address'])<2 || mb_strlen($d['street_address'])>255 || !filter_var($d['email'],FILTER_VALIDATE_EMAIL) || strlen($d['email'])>255) $errors[]='Complete all required fields. Names must be at least two characters.';
