  if (!preg_match('/^\d{4}$/',$d['zip_code'])) $errors[]='Enter a valid four-digit ZIP code.';
  $d['phone']=normalize_mobile($d['phone']);
  if (!preg_match(MOBILE_RE,$d['phone'])) $errors[]='Enter a valid Philippine mobile number.';
  if (!$errors && email_owned_by_another_account($pdo,$d['email'])) $errors[]='That email address belongs to another account. Use your own email address.';
  $resume=null;
  if (empty($_FILES['resume']['name'])) $errors[]='Please attach your resume or CV.';
  else {
    $f=$_FILES['resume']; $ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));
    $mime=$f['error']===UPLOAD_ERR_OK ? (new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']) : '';
    $allowedMimes=['pdf'=>['application/pdf'],'doc'=>['application/msword','application/vnd.ms-office'],'docx'=>['application/vnd.openxmlformats-officedocument.wordprocessingml.document']];
    if ($f['error']!==UPLOAD_ERR_OK || !isset($allowedMimes[$ext]) || !in_array($mime,$allowedMimes[$ext]??[],true) || $f['size']<1 || $f['size']>5*1024*1024) $errors[]='Resume must be a valid PDF or Word document up to 5 MB.';
    else { $dir=__DIR__.'/uploads/resumes'; if (!is_dir($dir)) mkdir($dir,0750,true); $resume=bin2hex(random_bytes(16)).'.'.$ext; if (!move_uploaded_file($f['tmp_name'],$dir.'/'.$resume)) { $errors[]='Resume upload failed.'; $resume=null; } }
  }
  if (!$errors) { $pdo->prepare('INSERT INTO careers_applications(purpose,first_name,middle_name,last_name,position_applied,phone,street_address,barangay_code,zip_code,email,resume_path) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$d['purpose'],$d['first_name'],$d['middle_name']?:null,$d['last_name'],$d['position_applied'],$d['phone'],$d['street_address'],$place['barangay_code'],$d['zip_code'],$d['email'],$resume]); $id=(int)$pdo->lastInsertId(); $pdo->prepare("INSERT INTO team_inbox_events(event_type,title,message,audience,entity_type,entity_id) VALUES('career_application','New career application',?, 'staff','career_application',?)")->execute([$d['first_name'].' '.$d['last_name'].' applied for '.$d['position_applied'].'.',$id]); $saved=true; }
}
$psgc=psgc_form_state($pdo,$d??[]);
$pageTitle='Careers'; $pageScripts='<script src="assets/js/psgc-select.js?v=' . filemtime(__DIR__ . '/assets/js/psgc-select.js') . '"></script>'; require 'includes/header.php'; render_toasts(array_map(static fn($message)=>['kind'=>'danger','text'=>$message],$errors)); if ($saved) render_toasts([['kind'=>'success','text'=>'Your career application was received.']]);
